-- BattleBallServer: monster stats by class and dungeon tier. GENERATED by BattleBall/SourceData/tools/build_monster_stats_sql.py.
-- Status: PROPOSED, from GDD section 7 (HP from the time-to-kill formula; ATK % of Max_ATK_Total; armor = damage reduction %). Edit on the admin page.
-- Depends on V009 to V012 (dungeon_boss, boss_template). Per-boss tuning: boss_template.hp_mult and atk_mult (default 1).
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS monster_stat_class (
  class_key     ENUM('MOB','ELITE','BOSS','MINI','FINAL') NOT NULL,
  tier          ENUM('early','mid','late') NOT NULL,
  ttk_seconds   DECIMAL(6,1)  NOT NULL,                 -- design time for the expected team to kill it
  hp            BIGINT UNSIGNED NOT NULL,
  atk_pct_min   DECIMAL(6,2)  NOT NULL,                 -- % of Max_ATK_Total per hit (random inside the range)
  atk_pct_max   DECIMAL(6,2)  NOT NULL,
  armor_pct_min DECIMAL(5,2)  NOT NULL,                 -- damage reduction of the monster, %
  armor_pct_max DECIMAL(5,2)  NOT NULL,
  action_gap_s  DECIMAL(4,1)  NULL,                     -- seconds between boss actions (GDD 7.5); NULL for small mobs
  note          VARCHAR(255)  NULL,
  updated_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  updated_by    VARCHAR(64)   NULL,
  PRIMARY KEY (class_key, tier)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @has_col = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'boss_template' AND COLUMN_NAME = 'hp_mult');
SET @ddl = IF(@has_col = 0, 'ALTER TABLE boss_template ADD COLUMN hp_mult DECIMAL(5,2) NOT NULL DEFAULT 1.00', 'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @has_col = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'boss_template' AND COLUMN_NAME = 'atk_mult');
SET @ddl = IF(@has_col = 0, 'ALTER TABLE boss_template ADD COLUMN atk_mult DECIMAL(5,2) NOT NULL DEFAULT 1.00', 'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

