-- What every dungeon fight contains, with the final numbers (class from the role, tier from the dungeon).
CREATE OR REPLACE VIEW v_dungeon_monster AS
SELECT d.dungeon_id, d.name_vi AS dungeon, d.tier, b.boss_id, b.name_vi AS boss, x.role,
  (CASE x.role WHEN 'NORMAL' THEN 'BOSS' WHEN 'MINI' THEN 'MINI' WHEN 'FINAL' THEN 'FINAL' ELSE COALESCE(x.mob_tier, 'MOB') END) AS class_key,
  ROUND(s.hp * b.hp_mult) AS hp,
  ROUND((s.atk_pct_min + s.atk_pct_max) / 200 * b.atk_mult * (SELECT CAST(value_json AS UNSIGNED) FROM balance_config WHERE config_key = 'max_atk_total')) AS atk_per_hit,
  (s.armor_pct_min + s.armor_pct_max) / 2 AS armor_reduction_pct,
  s.action_gap_s
FROM dungeon_boss x
JOIN dungeon_template d ON d.dungeon_id = x.dungeon_id
JOIN boss_template b ON b.boss_id = x.boss_id
JOIN monster_stat_class s ON s.tier = d.tier AND s.class_key = (CASE x.role WHEN 'NORMAL' THEN 'BOSS' WHEN 'MINI' THEN 'MINI' WHEN 'FINAL' THEN 'FINAL' ELSE COALESCE(x.mob_tier, 'MOB') END);

INSERT INTO static_data_version (domain, version, updated_by) VALUES ('MONSTER', 1, 'seed')
  ON DUPLICATE KEY UPDATE version = version + 1, updated_by = 'seed';
